<?php $base='../';require_once '../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('INSERT INTO service_packages(name,description,price,duration,features) VALUES(?,?,?,?,?)')->execute([$_POST['name'],$_POST['description'],$_POST['price'],$_POST['duration'],$_POST['features']]);header('Location: packages.php');exit;}$rows=db()->query('SELECT * FROM service_packages')->fetchAll();$title='Packages';include '../includes/header.php';?><section class="section"><div class="container"><h1>Packages</h1><form method="post" class="card p-4 my-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-2"><div class="col-md-2"><input class="form-control" name="name" placeholder="Name" required></div><div class="col-md-3"><input class="form-control" name="description" placeholder="Description"></div><div class="col-md-2"><input class="form-control" name="price" type="number" step=".01" placeholder="Price"></div><div class="col-md-2"><input class="form-control" name="duration" placeholder="Duration"></div><div class="col-md-2"><input class="form-control" name="features" placeholder="A|B|C"></div><div class="col-md-1"><button class="btn btn-gold">Add</button></div></div></form><div class="row g-3"><?php foreach($rows as $r):?><div class="col-md-3"><div class="card p-3"><h4 class="gold"><?=e($r['name'])?></h4><h5><?=number_format($r['price'],2)?> ETB</h5><p><?=e($r['description'])?></p><small><?=e($r['duration'])?></small></div></div><?php endforeach;?></div></div></section><?php include '../includes/footer.php';?>
